def amicable_numbers_sum(limit):
    def sum_of_divisors(n):
        divisors_sum = 1  # 1 is always a divisor
        sqrt_n = int(n**0.5)
        for i in range(2, sqrt_n + 1):
            if n % i == 0:
                divisors_sum += i
                if i != n // i:  # Add the complement divisor
                    divisors_sum += n // i
        return divisors_sum

    def is_amicable(a):
        b = sum_of_divisors(a)
        return b != a and sum_of_divisors(b) == a

    amicable_sum = 0
    for num in range(2, limit + 1):
        if is_amicable(num):
            amicable_sum += num

    return amicable_sum

# Example test
assert amicable_numbers_sum(999) == 504
```

