def max_aggregate(data):
    # Create a dictionary to store aggregate scores for each name
    aggregate_scores = {}

    # Iterate through the list of tuples
    for name, score in data:
        if name in aggregate_scores:
            aggregate_scores[name] += score
        else:
            aggregate_scores[name] = score

    # Find the maximum aggregate score and the corresponding name
    max_name, max_score = max(aggregate_scores.items(), key=lambda x: x[1])

    return (max_name, max_score)

# Example usage:
assert max_aggregate([('Juan Whelan',90),('Sabah Colley',88),('Peter Nichols',7),('Juan Whelan',122),('Sabah Colley',84)]) == ('Juan Whelan', 212)
```

