def find_kth(arr1, arr2, k):
    def kth_element(a, b, k):
        if not a:
            return b[k - 1]
        if not b:
            return a[k - 1]
        if k == 1:
            return min(a[0], b[0])

        mid_a = k // 2 if len(a) >= k // 2 else len(a)
        mid_b = k // 2 if len(b) >= k // 2 else len(b)

        if a[mid_a - 1] <= b[mid_b - 1]:
            return kth_element(a[mid_a:], b, k - mid_a)
        else:
            return kth_element(a, b[mid_b:], k - mid_b)

    return kth_element(arr1, arr2, k)

# Example assertion
assert find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5) == 6
```

