def move_num(s):
    letters = []
    numbers = []
    temp = ""

    for char in s:
        if char.isdigit():
            temp += char
        else:
            if temp:
                numbers.append(temp)
                temp = ""
            letters.append(char)

    if temp:
        numbers.append(temp)

    return ''.join(letters) + ''.join(numbers)

